// Extract complaints list from backend response
const response = $input.first().json;
const complaints = response.data || [];

if (!complaints.length) {
  return [{
    json: {
      has_stagnant: false,
      message: 'No complaints currently exceeding 5 days without response.',
      timestamp: new Date().toISOString()
    }
  }];
}

const results = [];
const defaultHigherAuthority = 'admin@nagardrishti.gov.in'; // Chief Municipal Commissioner
const portalUrl = 'http://localhost:3000';

for (const comp of complaints) {
  const publicNumber = comp.public_number || comp.id;
  const title = comp.title || 'Untitled civic report';
  const category = comp.category_name || 'General Municipal Issue';
  const department = comp.department_name || 'Unassigned Municipal Dept';
  const location = comp.location_text || 'Location not specified';
  const daysStagnant = Number(comp.days_stagnant || 5);
  const citizen = comp.reporter_name || 'Citizen';
  const email = comp.reporter_email || 'N/A';
  const phone = comp.reporter_phone || 'N/A';

  const recipients = [defaultHigherAuthority];
  if (comp.department_email && comp.department_email !== defaultHigherAuthority) {
    recipients.push(comp.department_email);
  }

  const subject = `🚨 [URGENT ESCALATION] Unattended Civic Complaint #${publicNumber} Exceeded ${daysStagnant} Days Without Response`;

  const html = `
    <div style="font-family: -apple-system, sans-serif; max-width: 620px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 10px; overflow: hidden;">
      <div style="background: #0f172a; padding: 20px 24px; color: #fff;">
        <div style="font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #38bdf8; font-weight: 700;">🏛 NAGAR DRISHTI MUNICIPAL MONITORING</div>
        <h2 style="margin: 6px 0 0; font-size: 18px;">5-Day SLA Breach Escalation Notice</h2>
      </div>
      <div style="background: #fee2e2; border-left: 4px solid #ef4444; padding: 14px 20px; margin: 18px 24px;">
        <strong style="color: #991b1b;">⚠️ Immediate Administrative Intervention Required</strong>
        <p style="margin: 4px 0 0; color: #7f1d1d; font-size: 13px;">
          Civic complaint <strong>#${publicNumber}</strong> has remained unresponded for <strong>${daysStagnant} consecutive days</strong> without status change or resolution.
        </p>
      </div>
      <div style="padding: 10px 24px 20px;">
        <table style="width: 100%; border-collapse: collapse; font-size: 13px;">
          <tr><td style="padding: 8px 0; color: #64748b; width: 35%;">Tracking ID:</td><td><strong>#${publicNumber}</strong></td></tr>
          <tr><td style="padding: 8px 0; color: #64748b;">Issue:</td><td><strong>${title}</strong></td></tr>
          <tr><td style="padding: 8px 0; color: #64748b;">Category:</td><td>${category}</td></tr>
          <tr><td style="padding: 8px 0; color: #64748b;">Designated Dept:</td><td><strong>${department}</strong></td></tr>
          <tr><td style="padding: 8px 0; color: #64748b;">Location:</td><td>${location}</td></tr>
          <tr><td style="padding: 8px 0; color: #64748b;">Citizen Reporter:</td><td>${citizen} (${email} · ${phone})</td></tr>
          <tr><td style="padding: 8px 0; color: #64748b;">Days Unattended:</td><td><span style="background:#ef4444;color:#fff;padding:2px 8px;border-radius:4px;font-weight:700;">${daysStagnant} Days</span></td></tr>
        </table>
        <div style="text-align: center; margin: 24px 0 10px;">
          <a href="${portalUrl}" style="background: #059669; color: #ffffff; padding: 10px 24px; text-decoration: none; border-radius: 6px; font-weight: 700; font-size: 13px; display: inline-block;">
            Open Admin Portal to Resolve ›
          </a>
        </div>
      </div>
      <div style="background: #f8fafc; border-top: 1px solid #e2e8f0; padding: 12px 24px; font-size: 11px; color: #64748b;">
        Escalated autonomously by Nagar Drishti Workflow C. All events logged into municipal compliance ledger.
      </div>
    </div>
  `;

  results.push({
    json: {
      has_stagnant: true,
      complaint_id: comp.id,
      public_number: publicNumber,
      title,
      category,
      department,
      days_stagnant: daysStagnant,
      higher_authority_emails: recipients,
      email_subject: subject,
      email_html: html,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

parameters.responseBody:
={{ JSON.stringify({
  success: true,
  message: '5-Day unresponded escalation processed. Alert emails dispatched to Higher Authorities.',
  escalated_count: $items().length,
  escalations: $items().map(i => ({
    complaint_id: i.json.complaint_id,
    public_number: i.json.public_number,
    days_stagnant: i.json.days_stagnant,
    recipients: i.json.higher_authority_emails
  }))
}) }}
